import {ACTIVE_GEMS,SUPPORT_GEMS} from './gems.js';
import {gearLabel} from './progression.js';
import {prepareShop,sellPrice,TICKET_PRICE,LEGENDARY_WEAPONS} from './shop.js';
const rarity=w=>w.rarity==='legendary'?'傳說':w.rarity==='epic'?'史詩':w.rarity==='rare'?'稀有':'普通';
export function bagCards(g){return `<h2>裝備收藏 <small>${g.bag.weapons.length} / 40</small></h2><p>此處查看收藏；切換「裝備」可換裝與配置寶石。</p><div class="inventory-cards">${g.bag.weapons.map(w=>`<article class="inventory-card ${w.rarity}"><span class="rarity">${rarity(w)} · ${g.equipped.includes(w.id)?'已裝備':'背包'}</span><h3>${w.icon} ${w.name}</h3><p>${w.desc||gearLabel(w)}</p><small>${w.sockets.length} 孔 · ${w.linked} 孔串連</small></article>`).join('')}</div>`}
export function shopView(g){
 if(!g.forgeUnlocked)return '<div class="shop-locked"><h2>商店尚未開放</h2><p>擊敗第 5、10、15 波 Boss 後，可買賣裝備與使用臨界卷。</p></div>';
 prepareShop(g);const prize=g.lastPrize;
 return `<div class="shop-wallet"><strong>金幣 ${g.gold}</strong><strong>臨界卷 ${g.tickets}</strong></div><section class="lottery-panel"><span class="eyebrow">THE THRESHOLD</span><h2>臨界召喚</h2><p>每張臨界卷必得一件傳說。武器 50%／未收藏傳說寶石 50%；寶石集齊後改為 100% 武器。</p><div class="camp-actions"><button class="secondary" data-buy="ticket" ${g.gold<TICKET_PRICE?'disabled':''}>購買臨界卷 · ${TICKET_PRICE} 金幣</button><button class="primary" id="drawLegend" ${g.tickets<1||g.bag.weapons.length>=40?'disabled':''}>召喚傳說 · 臨界卷 ×1</button></div>${g.bag.weapons.length>=40?'<p>背包已滿，請先出售裝備。</p>':''}${prize?`<div class="legend-prize" role="status"><span>傳說降臨 · ${prize.kind==='weapon'?'武器':'寶石'}</span><h3>${prize.icon} ${prize.name}</h3><p>${prize.desc}</p><small>已收入背包，可到裝備分頁配置。</small></div>`:''}<details><summary>查看傳說獎池</summary><div class="inventory-cards">${[...LEGENDARY_WEAPONS,...Object.values(SUPPORT_GEMS).filter(s=>s.rarity==='legendary')].map(w=>`<article><h3>${w.icon} ${w.name}</h3><p>${w.desc}</p></article>`).join('')}</div></details></section><h2>旅商裝備</h2><p>每位 Boss 後更新商品；金幣由擊杀小怪 +5、Boss +150 獲得。</p><div class="inventory-cards">${g.shop.stock.map((item,i)=>`<article class="inventory-card"><span class="rarity">${rarity(item.weapon)}</span><h3>${item.weapon.icon} ${item.weapon.name}</h3><p>${gearLabel(item.weapon)} · ${item.weapon.sockets.length} 孔</p><button class="secondary" data-buy="${i}" ${item.sold||g.gold<item.price||g.bag.weapons.length>=40?'disabled':''}>${item.sold?'已售出':item.price+' 金幣・購買'}</button></article>`).join('')}</div><h2>出售背包裝備</h2><p>已裝備物品受保護，不會出現在出售清單。</p><div class="inventory-cards">${g.bag.weapons.filter(w=>!g.equipped.includes(w.id)).map(w=>`<article class="inventory-card ${w.rarity}"><span class="rarity">${rarity(w)}</span><h3>${w.name}</h3><p>${w.desc||gearLabel(w)}</p><button class="secondary" data-sell="${w.id}">出售 · +${sellPrice(w)} 金幣</button></article>`).join('')||'<p>沒有可出售的備用裝備。</p>'}</div>`;
}
